import itertools
import json

def solve_puzzle():
    # Input variables based on the puzzle
    houses = [1, 2]  # numbered left to right as seen from across the street
    names = ["Eric", "Arnold"]
    favorite_book_genres = ["science fiction", "mystery"]

    solutions = []

    # Try all permutations for each attribute category
    for perm_names in itertools.permutations(names, len(houses)):
        # Map house -> name
        name_by_house = {house: perm_names[i] for i, house in enumerate(houses)}

        for perm_genres in itertools.permutations(favorite_book_genres, len(houses)):
            # Map house -> favorite book genre
            genre_by_house = {house: perm_genres[i] for i, house in enumerate(houses)}

            # Apply clues

            # 1. Eric is directly left of the person who loves mystery books.
            # Find house positions
            house_of_eric = next(h for h in houses if name_by_house[h] == "Eric")
            house_of_mystery = next(h for h in houses if genre_by_house[h] == "mystery")

            if house_of_eric + 1 != house_of_mystery:
                continue

            # If all constraints pass, record solution
            assignment = {
                house: {
                    "name": name_by_house[house],
                    "favorite book genres": genre_by_house[house],
                }
                for house in houses
            }
            solutions.append(assignment)

    if not solutions:
        raise ValueError("No solution found.")

    # If multiple solutions exist, choose the first (should be unique for this puzzle)
    sol = solutions[0]

    # Build output in the required JSON structure
    header = ["House", "name", "favorite book genres"]
    rows = []
    for house in houses:
        rows.append([str(house), sol[house]["name"], sol[house]["favorite book genres"]])

    result = {
        "solution": {
            "header": header,
            "rows": rows
        }
    }
    return result

if __name__ == "__main__":
    print(json.dumps(solve_puzzle(), ensure_ascii=False, indent=2))
